CREATE DATABASE IF NOT EXISTS barber_rammach CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE barber_rammach;
CREATE TABLE IF NOT EXISTS services (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(150) NOT NULL,category VARCHAR(60) NOT NULL DEFAULT 'coupe_moderne',description TEXT,price DECIMAL(8,2) NOT NULL,price_type ENUM('fixed','starting_from') NOT NULL DEFAULT 'fixed',duration INT NOT NULL,image VARCHAR(255),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS barbers (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,role VARCHAR(80),image VARCHAR(255),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS appointments (id INT PRIMARY KEY AUTO_INCREMENT,service_id INT NOT NULL,barber_id INT NOT NULL,service_name VARCHAR(150) NOT NULL,displayed_price VARCHAR(80) NOT NULL,price_type ENUM('fixed','starting_from') NOT NULL DEFAULT 'fixed',customer_name VARCHAR(120) NOT NULL,customer_phone VARCHAR(25) NOT NULL,customer_email VARCHAR(254) NOT NULL,appointment_date DATE NOT NULL,appointment_time TIME NOT NULL,duration INT NOT NULL,message TEXT,status ENUM('confirmed','cancelled','completed') NOT NULL DEFAULT 'confirmed',total_price DECIMAL(8,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(service_id) REFERENCES services(id),FOREIGN KEY(barber_id) REFERENCES barbers(id),INDEX availability_idx(barber_id,appointment_date,status));
CREATE TABLE IF NOT EXISTS appointment_slots (barber_id INT NOT NULL,appointment_date DATE NOT NULL,minute_of_day SMALLINT NOT NULL,appointment_id INT NOT NULL,PRIMARY KEY(barber_id,appointment_date,minute_of_day),FOREIGN KEY(barber_id) REFERENCES barbers(id),FOREIGN KEY(appointment_id) REFERENCES appointments(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS contacts (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(254) NOT NULL,phone VARCHAR(25) NOT NULL,subject VARCHAR(150) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gallery (id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(150),category VARCHAR(40),image VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews (id INT PRIMARY KEY AUTO_INCREMENT,customer_name VARCHAR(120),review TEXT,rating TINYINT NOT NULL CHECK(rating BETWEEN 1 AND 5),image VARCHAR(255),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
